//! CQ12 project omen locality: an occupied ordinary region, bound at declaration.
//! Omen locality is project-specific; the printed red-asset condition is checked at resolution.
use crate::{catalog,engine::RuleResult,model::*,rules::*};
use serde::{Deserialize,Serialize};
use std::collections::BTreeSet;
pub(crate) const ID:&str="CQ12";
pub(crate) const OMEN:&str="cq12-omen";
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct OmenWitness {pub region:usize,pub region_instance:String,pub occupant:Card,pub red_assets:Vec<Card>,pub turn:u32}
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
pub(crate) fn definition()->Definition{let mut a=ability(OMEN,"准备步骤先兆②：在本人明置角色所在地区生成邪教徒",Timing::Fast,vec![Cost::Assets(2)],vec![],vec![Op::CQ12Omen{witness:None}],None);a.activation_only=true;a.per_turn_limit=Some(1);with_abilities(vec![a])}
fn owns(o:&Op)->bool{match o{Op::CQ12Omen{..}=>true,Op::ForEachLivingPlayer(v)|Op::ForEachLivingPlayerFromActor(v)=>v.iter().any(owns),Op::IfTargetExhausted{exhausted,ready,..}=>owns(exhausted)||owns(ready),_=>false}}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("cq12-")||a.ops.iter().chain(a.modes.iter().flat_map(|m|&m.ops)).any(owns)}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{let mut expected=definition().abilities.remove(0);if let [Op::CQ12Omen{witness}]=a.ops.as_slice(){expected.ops=vec![Op::CQ12Omen{witness:witness.clone()}];}if id!=ID||!same(a,&expected){return Err("盖罗涅先兆须保留原费用、时点和限次程序".into())}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("盖罗涅先兆定义不可移植或改写".into())}Ok(())}
impl Game{
 pub(crate) fn cq12_regions(&self,actor:usize)->Vec<usize>{self.regions.iter().enumerate().filter(|(r,z)|self.region_live(*r)&&z.cards.iter().any(|c|c.controller==actor&&!c.face_down&&catalog::card(&c.definition).kind=="character")).map(|(r,_)|r).collect()}
 pub(crate) fn cq12_begin(&mut self,actor:usize,a:&Action)->RuleResult<()>{
 if *a!=(Action{card_id:a.card_id.clone(),ability_id:Some(OMEN.into()),region:a.region,..Action::new("activate")})||!matches!(self.window,Some(Window::Prepare)){return Err("盖罗涅先兆仅准备步骤声明本人手牌及占场地区".into())}
 let c=self.players.get(actor).and_then(|p|p.hand.iter().find(|c|Some(c.id.as_str())==a.card_id.as_deref()&&c.definition==ID&&c.controller==actor&&!c.face_down)).ok_or("先兆须来自本人实际手牌")?.clone();
 let r=a.region.filter(|r|self.cq12_regions(actor).contains(r)).ok_or("先兆须选择本人明置角色所在普通场上地区")?;
 let red_assets=self.players[actor].assets.iter().filter(|c|catalog::card(&c.definition).color=="红").take(2).cloned().collect::<Vec<_>>();
 let occupant=self.regions[r].cards.iter().find(|c|c.controller==actor&&!c.face_down&&catalog::card(&c.definition).kind=="character").unwrap().clone();
 let witness=OmenWitness{region:r,region_instance:self.regions[r].card.id.clone(),occupant,red_assets,turn:self.turn};let source=self.source_snapshot(&c,None);let mut spec=definition().abilities.remove(0);spec.ops=vec![Op::CQ12Omen{witness:Some(witness)}];self.check_timing(actor,&spec)?;let paid=self.pay_ability_costs(actor,&source,&spec,a)?;let frame=self.make_frame(actor,source,&spec,vec![],paid,Some(r));self.note(format!("{} 展示手牌深渊惧影盖罗涅发动先兆",self.players[actor].name));self.dispatch_frame(frame,spec.label,None,spec.response_policy);Ok(())
 }
 pub(crate) fn cq12_frame(&self,f:&ResolutionFrame)->RuleResult<()>{
 if f.source.card.definition==ID&&!matches!(f.ability_key.as_str(),OMEN|"deploy"|"reveal")&&!self.validated_cross_card_frame(f)?{return Err("盖罗涅不能借用外来来源能力帧".into())}
 if !f.ability_key.starts_with("cq12-")&&!f.steps.iter().any(|s|owns(&s.op)){return Ok(())}
 let [Step{context,op:Op::CQ12Omen{witness:Some(w)}}]=f.steps.as_slice()else{return Err("先兆须保留原声明见证".into())};let c=&f.source.card;
 if c.definition!=ID||c.face_down||c.controller!=f.actor||c.owner>=self.players.len()||f.actor>=self.players.len()||*context!=f.actor||f.ability_key!=OMEN||f.source.region.is_some()||f.source.source_region_instance.is_some()||f.source.play_source.is_some()||f.source.attachment_host_instance.is_some()||f.source.observed_death.is_some()||f.source.death_echo.is_some()||f.source.observed_exposure.is_some()||f.source.observed_mobility_grant.is_some()||!f.targets.is_empty()||f.chosen_region!=Some(w.region)||w.region>=self.regions.len()||w.turn!=self.turn||f.cursor>1||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted)||w.occupant.controller!=f.actor||w.occupant.face_down||catalog::card(&w.occupant.definition).kind!="character"||w.red_assets.len()>2||w.red_assets.iter().any(|a|a.controller!=f.actor||catalog::card(&a.definition).color!="红")||!self.turn_ability_usage.iter().any(|u|u.source_instance==c.id&&u.ability_key==OMEN&&u.turn==w.turn&&u.uses==1){return Err("先兆来源、占场见证、红资产、限次或程序损坏".into())}
 let mut ids=BTreeSet::new();for id in [&c.id,&w.region_instance,&w.occupant.id].into_iter().chain(w.red_assets.iter().map(|a|&a.id)){if !ids.insert(id)||!self.mystic_instance_number(id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b){return Err("先兆见证实体身份损坏".into())}}
 self.mobility_immutable_identity(c)?;self.mobility_immutable_identity(&w.occupant)?;for a in &w.red_assets{self.mobility_immutable_identity(a)?;}self.validate_batch20_payment(f,&[Cost::Assets(2)])
 }
 pub(crate) fn cq12_step(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.cq12_frame(f)?;if f.cursor!=1{return Err("先兆须经原结算入口".into())}let Op::CQ12Omen{witness:Some(w)}=&f.steps[0].op else{unreachable!()};if !self.players[f.actor].eliminated&&self.players[f.actor].assets.iter().filter(|c|catalog::card(&c.definition).color=="红").count()>=2&&self.region_live(w.region)&&self.regions[w.region].card.id==w.region_instance{let c=self.make_generated(crate::generated::GeneratedKind::Cultist,f.actor)?;let id=c.id.clone();self.regions[w.region].cards.push(c);self.enter_triggers(f.actor,"TK008",&id,false);}Ok(())}
 pub(crate) fn validate_cq12_state(&self)->RuleResult<()>{let mut seen=BTreeSet::new();for i in &self.stack{if let Some(f)=&i.frame{self.cq12_frame(f)?;if f.ability_key==OMEN&&(i.card.is_some()||i.id!=f.frame_id||i.controller!=f.actor||i.target.is_some()||i.deploy_region.is_some()||i.reveal||f.cursor!=0||!seen.insert(&f.frame_id)){return Err("先兆事务外壳或独占帧损坏".into())}}}for e in &self.effects{match e{Effect::Frame{frame}if frame.ability_key.starts_with("cq12-")||frame.steps.iter().any(|s|owns(&s.op))=>return Err("先兆单步不能脱离原响应事务".into()),Effect::Declare{declaration:d}if related(&d.ability)=>return Err("先兆不是场上触发".into()),_=>()}}if let Some(p)=&self.pending{match &p.resolution{ChoiceResolution::Frame{frame,..}if frame.ability_key.starts_with("cq12-")||frame.steps.iter().any(|s|owns(&s.op))=>return Err("先兆没有帧内选择".into()),ChoiceResolution::Declare{declaration:d,..}if related(&d.ability)=>return Err("先兆没有触发选择".into()),_=>()}}Ok(())}
}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]
pub struct CostDraft {pub actor:usize,pub turn:u32,pub card:Card,pub action:Action}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]
pub struct SacrificePayment {pub before:u32,pub victims:Vec<SourceSnapshot>}
impl Game {
 fn cq12_victims(&self,actor:usize)->Vec<SourceSnapshot>{self.regions.iter().enumerate().filter(|(_,r)|!r.vacant).flat_map(|(r,z)|z.cards.iter().filter(move|c|c.controller==actor&&!c.face_down&&catalog::card(&c.definition).kind=="character").map(move|c|self.source_snapshot(c,Some(r)))).collect()}
 fn cq12_cost_options(&self,actor:usize)->Vec<ChoiceOption>{self.cq12_victims(actor).iter().map(|s|ChoiceOption{id:s.card.id.clone(),label:format!("牺牲 {}",catalog::card(&s.card.definition).name),card:None}).collect()}
 fn cq12_cost_draft(&self,d:&CostDraft)->RuleResult<()>{let a=&d.action;if d.actor>=self.players.len()||d.turn!=self.turn||d.card.definition!=ID||d.card.controller!=d.actor||*a!=(Action{card_id:Some(d.card.id.clone()),region:if a.kind=="deploy"{a.region}else{None},..Action::new(&a.kind)}){return Err("盖罗涅额外费用原声明损坏".into())}let live=match a.kind.as_str(){"deploy" if self.status=="playing"&&!self.players[d.actor].eliminated&&self.stack.is_empty()&&self.priority_team==self.team(d.actor)&&self.window==Some(Window::Action(self.team(d.actor)))=>self.character_play_source(d.actor,&d.card.id,false).ok().map(|(c,_)|c),"reveal" if self.status=="playing"&&!self.players[d.actor].eliminated&&self.priority_team==self.team(d.actor)=>self.board(&d.card.id).filter(|(_,c)|c.face_down).map(|(_,c)|c.clone()),_=>None}.ok_or("盖罗涅原付费入口或来源已变化")?;if !same(&live,&d.card)||!self.loyalty(d.actor,ID){return Err("盖罗涅费用来源或忠诚已变化".into())}let n=self.cq12_victims(d.actor).len()as u32;let cost=if a.kind=="deploy"{self.effective_cost(d.actor,&d.card)}else{self.paid_reveal_cost(d.actor,&d.card)};if self.resources(d.actor)<cost.saturating_sub(n){return Err("盖罗涅即使全部合法牺牲也无法付费".into())}Ok(())}
 pub(crate) fn cq12_begin_cost(&mut self,actor:usize,c:&Card,a:&Action)->RuleResult<()>{let d=CostDraft{actor,turn:self.turn,card:c.clone(),action:a.clone()};self.cq12_cost_draft(&d)?;let opts=self.cq12_cost_options(actor);let max=opts.len();self.choice(actor,"cq12-sacrifice","盖罗涅：选择牺牲X个角色以减费".into(),opts,0,max,None,ChoiceResolution::CQ12Payment{draft:Box::new(d)});Ok(())}
 pub(crate) fn cq12_choose_cost(&mut self,d:CostDraft,seat:usize,a:&Action,ids:&[String])->RuleResult<()>{self.cq12_cost_draft(&d)?;if seat!=d.actor||*a!=(Action{choice_id:a.choice_id.clone(),selected:a.selected.clone(),..Action::new("choose")}){return Err("盖罗涅仅接受本人原牺牲选择".into())}let mut original=d.action;original.cost_selected=Some(ids.to_vec());self.apply_inner(seat,original)}
 pub(crate) fn cq12_pay(&mut self,actor:usize,c:&Card,a:&Action)->RuleResult<Vec<PaidCost>>{let mut original=a.clone();original.cost_selected=None;let d=CostDraft{actor,turn:self.turn,card:c.clone(),action:original};self.cq12_cost_draft(&d)?;let ids=a.cost_selected.as_ref().ok_or("盖罗涅尚未选择额外牺牲")?;if ids.iter().collect::<BTreeSet<_>>().len()!=ids.len(){return Err("不能重复牺牲同一角色".into())}let eligible=self.cq12_victims(actor);let victims=ids.iter().map(|id|eligible.iter().find(|s|&s.card.id==id).cloned().ok_or("牺牲必须为本人操控的明置场上角色".to_string())).collect::<RuleResult<Vec<_>>>()?;let face=a.kind=="deploy";let before=if face{self.effective_cost(actor,c)}else{self.paid_reveal_cost(actor,c)};let mut paid=self.pay_printed_reduced(actor,c,face,false,victims.len()as u32)?;let wave=victims.iter().map(|s|(s.card.id.clone(),RemovalCause::Sacrifice,s.clone())).collect();self.destroy_wave_as(actor,wave);paid.push(PaidCost::CQ12Sacrifice(Box::new(SacrificePayment{before,victims})));Ok(paid)}
 pub(crate) fn cq12_play_frame(&self,f:&ResolutionFrame)->RuleResult<()>{let c=&f.source.card;let reveal=f.ability_key=="reveal";self.validate_resource_frame(f)?;let [PaidCost::Assets(_),PaidCost::CQ12Sacrifice(p)]=f.already_paid.as_slice()else{return Err("盖罗涅缺少真实资产和牺牲费用收据".into())};if c.definition!=ID||c.controller!=f.actor||c.owner>=self.players.len()||f.actor>=self.players.len()||f.cursor!=0||!matches!(f.guard,GuardState::Unchecked)||!f.steps.is_empty()||!f.targets.is_empty()||f.source.region!=f.chosen_region||f.source.region.is_none_or(|r|r>=self.regions.len())||if reveal{!c.face_down||f.source.play_source.is_some()}else{f.ability_key!="deploy"||c.face_down||!f.source.valid_character_play()}||p.before>5||f.money_units(0)!=p.before.saturating_sub(p.victims.len()as u32)as usize||p.victims.iter().map(|v|&v.card.id).collect::<BTreeSet<_>>().len()!=p.victims.len()||p.victims.iter().any(|v|v.card.controller!=f.actor||v.card.face_down||v.card.id==c.id||catalog::card(&v.card.definition).kind!="character"||v.region.is_none_or(|r|r>=self.regions.len())){return Err("盖罗涅派遣/现身支付或来源损坏".into())}self.mobility_immutable_identity(c)?;for s in &p.victims{self.mobility_immutable_identity(&s.card)?;if !self.mystic_instance_number(&s.card.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b){return Err("盖罗涅牺牲身份损坏".into())}}Ok(())}
 pub(crate) fn validate_cq12_payment_state(&self)->RuleResult<()>{for i in &self.stack{if i.card.as_ref().is_some_and(|c|c.definition==ID)||i.frame.as_ref().is_some_and(|f|f.source.card.definition==ID&&matches!(f.ability_key.as_str(),"deploy"|"reveal")){let f=i.frame.as_ref().ok_or("盖罗涅角色事务缺原帧")?;self.cq12_play_frame(f)?;if i.id!=f.frame_id||i.controller!=f.actor||i.target.is_some()||i.reveal!=(f.ability_key=="reveal")||i.deploy_region!=f.chosen_region||i.card.as_ref().is_none_or(|c|!self.pack_a_transaction_matches(f,c)){return Err("盖罗涅角色实际事务与帧不符".into())}}}if let Some(p)=&self.pending{if let ChoiceResolution::CQ12Payment{draft:d}=&p.resolution{self.cq12_cost_draft(d)?;let opts=self.cq12_cost_options(d.actor);let expected=Choice{id:p.choice.id.clone(),kind:"cq12-sacrifice".into(),title:"盖罗涅：选择牺牲X个角色以减费".into(),description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(d.actor),min:Some(0),max:Some(opts.len()),options:opts,preview_cards:vec![],amount:None,allow_decline:Some(true)};if p.seat!=d.actor||!self.mystic_instance_valid(&p.choice.id)||!same(&p.choice,&expected){return Err("盖罗涅原额外费用待选损坏".into())}}}Ok(())}
}
